export interface AttendanceState {
  totalClasses: number;
  attendedClasses: number;
  examDate: string; // YYYY-MM-DD
  holidays: string[]; // Array of YYYY-MM-DD
}

export interface AttendanceStats {
  currentPercentage: number;
  isSafe: boolean; // > 75%
  classesUntilExam: number; // Total slots
  bunkableClasses: number; // How many can be skipped safely
  requiredClasses: number; // How many consecutive must be attended if unsafe
  tomorrowImpact: number; // Percentage if absent tomorrow
}

import { AttendanceState, AttendanceStats } from '../types';

const DAILY_CLASSES = 6;
const TARGET_PERCENTAGE = 75;

export const isWeekend = (date: Date): boolean => {
  const day = date.getDay();
  return day === 0 || day === 6; // Sunday = 0, Saturday = 6
};

export const getWorkingDaysBetween = (start: Date, end: Date, holidays: string[]): number => {
  let count = 0;
  const current = new Date(start);

  // Normalize to start of day
  current.setHours(0, 0, 0, 0);
  const endDate = new Date(end);
  endDate.setHours(0, 0, 0, 0);

  // Avoid infinite loops if dates are wrong
  if (current >= endDate) return 0;

  while (current < endDate) {
    const dateString = current.toISOString().split('T')[0];
    if (!isWeekend(current) && !holidays.includes(dateString)) {
      count++;
    }
    current.setDate(current.getDate() + 1);
  }
  return count;
};

export const calculateStats = (state: AttendanceState): AttendanceStats => {
  const { totalClasses, attendedClasses, examDate, holidays } = state;

  // 1. Current Percentage
  const currentPercentage = totalClasses === 0 ? 0 : (attendedClasses / totalClasses) * 100;

  // 2. Classes until exam
  const today = new Date();
  const exam = new Date(examDate);
  // If exam date is invalid or in past, assume 0 future days
  const validExamDate = !isNaN(exam.getTime()) && exam > today;

  const workingDaysLeft = validExamDate ? getWorkingDaysBetween(today, exam, holidays) : 0;
  const classesUntilExam = workingDaysLeft * DAILY_CLASSES;

  // 3. Bunkable Classes logic
  // "How many classes you can absent until exam"
  // We assume we want to MAXIMIZE absence while keeping Final % >= 75
  // Final Total = Current Total + classesUntilExam
  // Let X be classes attended in future.
  // (CurrentAttended + X) / (CurrentTotal + classesUntilExam) >= 0.75
  // X >= 0.75 * (CurrentTotal + classesUntilExam) - CurrentAttended

  const finalTotal = totalClasses + classesUntilExam;
  const minRequiredTotalAttended = Math.ceil((TARGET_PERCENTAGE / 100) * finalTotal);
  const minFutureAttended = Math.max(0, minRequiredTotalAttended - attendedClasses);

  // bunkable = total available future classes - minimum we must attend
  // If bunkable is negative, it means even attending everything isn't enough (or 0)
  let bunkableClasses = classesUntilExam - minFutureAttended;
  if (bunkableClasses < 0) bunkableClasses = 0;

  // 4. Required to recover (if currently unsafe)
  // If current < 75, how many consecutive classes (N) needed?
  // (Attended + N) / (Total + N) >= 0.75
  // Attended + N >= 0.75*Total + 0.75N
  // 0.25N >= 0.75*Total - Attended
  // N >= (0.75*Total - Attended) / 0.25
  let requiredClasses = 0;
  if (currentPercentage < TARGET_PERCENTAGE) {
     const needed = (0.75 * totalClasses - attendedClasses) / 0.25;
     requiredClasses = Math.ceil(needed);
  }

  // 5. Tomorrow Impact
  // If absent tomorrow: Total + 6, Attended + 0
  const tomorrowTotal = totalClasses + DAILY_CLASSES;
  const tomorrowPercentage = (attendedClasses / tomorrowTotal) * 100;

  return {
    currentPercentage,
    isSafe: currentPercentage >= TARGET_PERCENTAGE,
    classesUntilExam,
    bunkableClasses,
    requiredClasses,
    tomorrowImpact: tomorrowPercentage
  };
};

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';

export const CustomCursor: React.FC = () => {
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [isHovering, setIsHovering] = useState(false);

  useEffect(() => {
    const mouseMove = (e: MouseEvent) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };

    // Add global hover listeners for interaction states
    const handleMouseOver = (e: MouseEvent) => {
        if ((e.target as HTMLElement).tagName === 'BUTTON' || (e.target as HTMLElement).tagName === 'A' || (e.target as HTMLElement).tagName === 'INPUT') {
            setIsHovering(true);
        } else {
            setIsHovering(false);
        }
    }

    window.addEventListener('mousemove', mouseMove);
    window.addEventListener('mouseover', handleMouseOver);

    return () => {
      window.removeEventListener('mousemove', mouseMove);
      window.removeEventListener('mouseover', handleMouseOver);
    };
  }, []);

  return (
    <motion.div
      className="fixed top-0 left-0 w-8 h-8 rounded-full border border-cyan-400 pointer-events-none z-50 mix-blend-difference hidden md:block"
      animate={{
        x: mousePosition.x - 16,
        y: mousePosition.y - 16,
        scale: isHovering ? 2.5 : 1,
        backgroundColor: isHovering ? "rgba(34, 211, 238, 0.1)" : "transparent",
        borderColor: isHovering ? "rgba(34, 211, 238, 0.5)" : "rgba(34, 211, 238, 1)"
      }}
      transition={{
        type: "spring",
        stiffness: 150,
        damping: 15,
        mass: 0.1
      }}
    />
  );
};

