    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1 } }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: { y: 0, opacity: 1 }
  };

  return (
    <div className="min-h-screen py-20 px-4 md:px-12 max-w-7xl mx-auto">
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="grid grid-cols-1 lg:grid-cols-2 gap-12"
      >
        {/* Controls Section */}
        <motion.div variants={itemVariants} className="space-y-8">
          <div className="glass-panel p-8 rounded-3xl neon-glow relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-cyan-500/10 rounded-full blur-3xl transform translate-x-16 -translate-y-16 group-hover:bg-cyan-500/20 transition-all duration-500"></div>

            <h2 className="text-3xl font-bold mb-8 text-white">Input Data</h2>

            <div className="space-y-6">
              {/* Total Classes */}
              <div className="space-y-2">
                <label className="text-slate-400 text-sm uppercase tracking-wider font-semibold">Total Classes Held</label>
                <input
                  type="number"
                  min="0"
                  value={state.totalClasses || ''}
                  onChange={(e) => handleChange('totalClasses', parseInt(e.target.value) || 0)}
                  className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-4 text-white focus:outline-none focus:border-cyan-500 transition-colors text-lg"
                  placeholder="e.g. 120"
                />
              </div>

              {/* Attended Classes */}
              <div className="space-y-2">
                <label className="text-slate-400 text-sm uppercase tracking-wider font-semibold">Classes Attended</label>
                <input
                  type="number"
