                    <motion.span 
                        className="text-6xl font-bold text-white tracking-tighter"
                        initial={{ opacity: 0, scale: 0.5 }}
                        animate={{ opacity: 1, scale: 1 }}
                        key={stats?.currentPercentage}
                    >
                        {stats?.currentPercentage.toFixed(1)}%
                    </motion.span>
                    <span className={`mt-2 px-3 py-1 rounded-full text-xs font-bold uppercase ${stats?.isSafe ? 'bg-cyan-500/20 text-cyan-300' : 'bg-red-500/20 text-red-300'}`}>
                        {stats?.isSafe ? 'Safe Zone' : 'Danger Zone'}
