                <div className="absolute inset-0 bg-gradient-to-br from-green-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <h4 className="text-slate-400 text-sm font-bold uppercase tracking-wider mb-2">Bunkable Classes</h4>
                <div className="flex items-end gap-2">
                    <span className="text-4xl font-bold text-white">
                        {stats?.bunkableClasses}
                    </span>
                    <span className="text-sm text-slate-500 mb-1 pb-1">classes</span>
                </div>
                <p className="text-xs text-slate-400 mt-2">
                    You can miss this many future classes and stay above 75%.
                </p>
            </div>

            {/* Recovery Card */}
            <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group">
                <div className="absolute inset-0 bg-gradient-to-br from-purple-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <h4 className="text-slate-400 text-sm font-bold uppercase tracking-wider mb-2">Must Attend</h4>
                <div className="flex items-end gap-2">
                    <span className="text-4xl font-bold text-white">
                        {stats?.requiredClasses}
                    </span>
                    <span className="text-sm text-slate-500 mb-1 pb-1">consecutive</span>
                </div>
                 <p className="text-xs text-slate-400 mt-2">
                    Classes required to get back to 75% threshold.
                </p>
            </div>

            {/* Tomorrow Projection */}
            <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group">
                 <div className="absolute inset-0 bg-gradient-to-br from-orange-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <h4 className="text-slate-400 text-sm font-bold uppercase tracking-wider mb-2">If Absent Tomorrow</h4>
                <div className="flex items-end gap-2">
                    <span className={`text-4xl font-bold ${(stats?.tomorrowImpact || 0) < 75 ? 'text-red-400' : 'text-orange-300'}`}>
                        {stats?.tomorrowImpact.toFixed(2)}%
                    </span>
                </div>
                <p className="text-xs text-slate-400 mt-2">
                    Your percentage drops to this if you miss all 6 classes tomorrow.
                </p>
            </div>

        </motion.div>
      </motion.div>
    </div>
  );
};

