  const containerVariants: Variants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1, delayChildren: 0.2 } }
  };

  // FIX: Explicitly typed with `Variants` to fix type inference errors.
  const itemVariants: Variants = {
    hidden: { y: 20, opacity: 0 },
    visible: { y: 0, opacity: 1, transition: { type: 'spring', stiffness: 100 } }
  };

  const StatCard = ({ icon, title, value, unit, description, colorClass }: any) => (
    <motion.div variants={itemVariants} className="glass-panel p-6 rounded-2xl relative overflow-hidden group border border-white/10">
      <div className={`absolute -inset-px bg-gradient-to-br ${colorClass} to-transparent opacity-0 group-hover:opacity-30 transition-opacity duration-500 rounded-2xl`} />
      <div className="flex items-start gap-4">
        <div className={`p-2 rounded-lg bg-slate-800 border border-slate-700`}>
          <Icon name={icon} className="w-6 h-6 text-cyan-400" />
        </div>
        <div>
          <h4 className="text-slate-400 text-sm font-bold uppercase tracking-wider mb-1">{title}</h4>
          <div className="flex items-baseline gap-2">
            <span className="text-4xl font-bold text-white tracking-tighter">{value}</span>
            {unit && <span className="text-sm text-slate-500">{unit}</span>}
          </div>
          <p className="text-xs text-slate-400 mt-2">{description}</p>
        </div>
      </div>
    </motion.div>
  );

  return (
    <div className="min-h-screen py-20 px-4 md:px-12 max-w-7xl mx-auto">
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="grid grid-cols-1 lg:grid-cols-12 gap-8"
      >
        {/* Controls Section */}
        <motion.div variants={itemVariants} className="lg:col-span-5">
          <div className="glass-panel p-8 rounded-3xl neon-glow h-full">
            <h2 className="text-3xl font-bold mb-8 text-white">Control Panel</h2>
            <div className="space-y-6">
              {[
                { name: 'totalClasses', label: 'Total Classes Held', type: 'number', icon: 'total', placeholder: 'e.g. 120' },
                { name: 'attendedClasses', label: 'Classes Attended', type: 'number', icon: 'attended', placeholder: 'e.g. 95' },
                { name: 'examDate', label: 'Exam Start Date', type: 'date', icon: 'exam' }
              ].map(field => (
                <div key={field.name} className="space-y-2">
                  <label className="flex items-center gap-2 text-slate-400 text-sm uppercase tracking-wider font-semibold">
                    <Icon name={field.icon} className="w-4 h-4" />
                    {field.label}
                  </label>
                  <input
                    type={field.type}
                    min="0"
                    value={(state as any)[field.name] || ''}
                    onChange={(e) => handleChange(field.name as keyof AttendanceState, field.type === 'number' ? (parseInt(e.target.value) || 0) : e.target.value)}
                    className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-cyan-500/50 focus:border-cyan-500 transition-all text-base"
                    placeholder={field.placeholder}
                    {...(field.type === 'date' ? { className: 'w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-cyan-500/50 focus:border-cyan-500 transition-all text-base [color-scheme:dark]' } : {})}
                  />
                </div>
              ))}
              <div className="space-y-2">
                <label className="flex items-center gap-2 text-slate-400 text-sm uppercase tracking-wider font-semibold">
                  <Icon name="holiday" className="w-4 h-4" />
                  Holidays (Optional)
                </label>
                <div className="flex gap-2">
                  <input type="date" id="holidayInput" className="bg-slate-900/50 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm flex-grow [color-scheme:dark]" />
                  <button onClick={() => {
                    const input = document.getElementById('holidayInput') as HTMLInputElement;
                    if (input.value && !state.holidays.includes(input.value)) {
                      handleChange('holidays', [...state.holidays, input.value].sort());
                      input.value = '';
                    }
                  }} className="px-4 py-2 bg-cyan-600 hover:bg-cyan-500 text-white rounded-lg text-sm font-bold transition-colors">Add</button>
                </div>
                {state.holidays.length > 0 && (
                  <div className="flex flex-wrap gap-2 pt-2">
                    {state.holidays.map(h => (
                      <span key={h} className="bg-slate-800 text-slate-300 text-xs px-2 py-1 rounded-full flex items-center gap-1.5">
                        {h}
                        <button onClick={() => handleChange('holidays', state.holidays.filter(d => d !== h))} className="text-red-400 hover:text-red-300 font-bold">×</button>
                      </span>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        </motion.div>

        {/* Analytics Section */}
        <motion.div variants={itemVariants} className="lg:col-span-7 space-y-8">
          <div className="glass-panel p-8 rounded-3xl relative overflow-hidden flex flex-col items-center justify-center text-center min-h-[400px]">
             <motion.div 
              className={`absolute inset-0 transition-colors duration-1000 ${stats?.isSafe ? 'bg-cyan-900/20' : 'bg-red-900/20'}`}
            />
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-950/5 via-slate-950/50 to-slate-950"></div>

            <h3 className="text-slate-400 font-medium mb-4 uppercase tracking-widest text-sm z-10">Current Attendance</h3>
            <div className="relative z-10">
              <svg className="w-64 h-64 transform -rotate-90" viewBox="0 0 256 256">
                <defs>
                  <filter id="glow-cyan" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="0" dy="0" stdDeviation="4.5" floodColor="#22d3ee" /></filter>
                  <filter id="glow-red" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="0" dy="0" stdDeviation="4.5" floodColor="#f87171" /></filter>
                </defs>
                <circle cx="128" cy="128" r="120" stroke="#1e293b" strokeWidth="12" fill="transparent" />
                <motion.circle cx="128" cy="128" r="120" stroke={stats?.isSafe ? "#22d3ee" : "#f87171"} strokeWidth="12" fill="transparent" strokeDasharray={2 * Math.PI * 120} strokeLinecap="round"
                  initial={{ strokeDashoffset: 2 * Math.PI * 120 }}
                  animate={{ strokeDashoffset: 2 * Math.PI * 120 * (1 - (stats?.currentPercentage || 0) / 100) }}
                  transition={{ duration: 1.5, type: "spring", stiffness: 50, damping: 15 }}
                  style={{ filter: `url(#glow-${stats?.isSafe ? 'cyan' : 'red'})` }} />
              </svg>
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <AnimatePresence mode="wait">
                  <motion.span className="text-7xl font-bold text-white tracking-tighter bg-clip-text text-transparent bg-gradient-to-b from-white to-slate-400 drop-shadow-lg" key={stats?.currentPercentage.toFixed(1)}
                    initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 20 }} transition={{ duration: 0.3 }}>
                    {stats?.currentPercentage.toFixed(1)}%
                  </motion.span>
                </AnimatePresence>
                <AnimatePresence mode="wait">
                  <motion.span key={stats?.isSafe ? 'safe' : 'danger'} initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.8 }} transition={{ duration: 0.3 }}
                    className={`mt-2 px-4 py-1.5 rounded-full text-xs font-bold uppercase tracking-wider ${stats?.isSafe ? 'bg-cyan-500/20 text-cyan-300' : 'bg-red-500/20 text-red-300'} border ${stats?.isSafe ? 'border-cyan-500/30' : 'border-red-500/30'}`}>
                    {stats?.isSafe ? 'Safe Zone' : 'Danger Zone'}
                  </motion.span>
                </AnimatePresence>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <StatCard icon="bunk" title="Bunkable" value={stats?.bunkableClasses} unit="classes" description="Can be missed while staying above 75%." colorClass="from-green-500/10" />
              <StatCard icon="attend" title="Must Attend" value={stats?.requiredClasses} unit="classes" description="Needed consecutively to reach 75%." colorClass="from-purple-500/10" />
              <StatCard icon="risk" title="Tomorrow Risk" value={`${stats?.tomorrowImpact.toFixed(1)}%`} unit="if absent" description="Your new percentage if you miss tomorrow." colorClass="from-orange-500/10" />
          </div>
        </motion.div>
      </motion.div>
    </div>
  );
};
